begin;
insert into public.cs_character_promo_delivery_plans(id,promo_id,character_id,network,account_id,scheduled_at,status,caption)
select '00000000-0000-0000-0000-000000000021',promo_id,character_id,'facebook','146219355471397',scheduled_at,'blocked_assets',null from public.cs_character_promo_delivery_plans where id='00000000-0000-0000-0000-000000000020';
create table public.control_ticket(label text primary key,ticket jsonb);
select public.assert_ok((public.cs_read_character_promo_plan_controls('00000000-0000-0000-0000-000000000021')->>'withdrawn')::boolean=false,'read-only current cohort');
select public.assert_ok((select count(*)=0 from cs_promo_private.plan_control_reviews),'GET creates no tickets');
insert into control_ticket values('withdraw',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','withdraw','00000000-0000-0000-0000-000000000001'));
select public.assert_ok(ticket->'snapshot'->>'action'='withdraw' and length(ticket->>'digest')=64,'explicit review opaque digest') from control_ticket where label='withdraw';
select public.assert_ok(not cs_promo_private.plan_withdrawn('00000000-0000-0000-0000-000000000021'),'preview is not withdrawal');
select public.assert_ok(public.cs_save_character_promo_plan_control(jsonb_set(ticket->'snapshot','{action}','"restore"'),ticket->>'digest','00000000-0000-0000-0000-000000000001') is null,'tampered snapshot rejected') from control_ticket where label='withdraw';
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',repeat('f',64),'00000000-0000-0000-0000-000000000001') is null,'wrong digest rejected') from control_ticket where label='withdraw';
select public.assert_ok((public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001')->>'withdrawn')::boolean,'explicit withdrawal committed') from control_ticket where label='withdraw';
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') is null,'save not silently retried') from control_ticket where label='withdraw';
select public.assert_ok((public.cs_read_character_promo_plan_control_result((ticket#>>'{snapshot,reviewId}')::uuid,'00000000-0000-0000-0000-000000000001')->>'withdrawn')::boolean,'unknown response reconciled by immutable review ID') from control_ticket where label='withdraw';
select public.assert_ok((public.cs_read_character_promo_gates('00000000-0000-0000-0000-000000000020')->>'pendingSiblingGatePlans')::int=0,'explicitly withdrawn sibling excluded');
select public.assert_ok(public.cs_claim_character_promo('00000000-0000-0000-0000-000000000020',repeat('a',64),'{}') is null,'withdrawal never approves remaining destination');
select public.assert_ok(public.cs_claim_character_promo('00000000-0000-0000-0000-000000000021',repeat('a',64),'{}') is null,'withdrawn target cannot claim');
insert into control_ticket values('edit-withdrawn',public.cs_review_character_promo_plan_edit('00000000-0000-0000-0000-000000000021','Edited caption while stopped',to_char((clock_timestamp()+interval '1 day') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'00000000-0000-0000-0000-000000000001'));
select public.assert_ok(public.cs_save_character_promo_plan_edit(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') is not null,'caption authoring can edit stopped plan without restoring') from control_ticket where label='edit-withdrawn';
select public.assert_ok(cs_promo_private.plan_withdrawn('00000000-0000-0000-0000-000000000021'),'authoring never silently restores');
update cs_promo_private.owners set enabled=false;
update cs_promo_private.owners set enabled=true;
select public.assert_ok(cs_promo_private.plan_withdrawn('00000000-0000-0000-0000-000000000021'),'revocation never undoes stop');
insert into control_ticket values('restore',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','restore','00000000-0000-0000-0000-000000000001'));
select public.assert_ok((public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001')->>'withdrawn')::boolean=false,'explicit preclaim restore') from control_ticket where label='restore';
select public.assert_ok((select count(*)=0 from cs_promo_private.gates),'restore invents no confirmations');
select public.assert_ok((select count(*)=2 from cs_promo_private.plan_control_events),'both immutable cohort events retained');
insert into control_ticket values('revoked-review',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','withdraw','00000000-0000-0000-0000-000000000001'));
update cs_promo_private.owners set enabled=false;
update cs_promo_private.owners set enabled=true;
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') is null,'old epoch preview cannot confirm after restoration') from control_ticket where label='revoked-review';
-- Review before another cohort edit cannot silently act on its changed membership.
insert into control_ticket values('stale',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000021','withdraw','00000000-0000-0000-0000-000000000001'));
insert into control_ticket values('other',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000020','withdraw','00000000-0000-0000-0000-000000000001'));
select public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') from control_ticket where label='other';
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') is null,'cohort CAS rejects stale effect') from control_ticket where label='stale';
insert into control_ticket values('other-restore',public.cs_review_character_promo_plan_control('00000000-0000-0000-0000-000000000020','restore','00000000-0000-0000-0000-000000000001'));
select public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') from control_ticket where label='other-restore';
select public.assert_ok(public.cs_save_character_promo_plan_control(ticket->'snapshot',ticket->>'digest','00000000-0000-0000-0000-000000000001') is null,'cohort change then revert cannot revive old ticket') from control_ticket where label='stale';
select public.assert_ok(not has_function_privilege('authenticated','public.cs_save_character_promo_plan_control(jsonb,text,uuid)','EXECUTE'),'browser cannot write cohort');
select public.assert_ok(not has_table_privilege('service_role','cs_promo_private.plan_controls','UPDATE'),'service cannot bypass audited action');
commit;
